import { cn } from '@cellhive/ui';
import { CircleAlert, CirclePause, Sparkles } from 'lucide-react';
import { useTranslation } from 'react-i18next';

import { aiCellStateOf } from '../../../lib/ai/ai-field';

import type { GridField } from '../../../grid';
import type { RecordDto } from '@cellhive/contracts';

/**
 * "Generated by AI" under the value of an AI field in the record panel
 * (T915, research S8 §5.6): or what the value waits for (generating,
 * paused) and when the AI could not generate it. Nothing for an empty
 * value with nothing pending, nor for a locked field (its value is hidden).
 */
export function AiMarker({
  field,
  record,
}: {
  readonly field: GridField;
  readonly record: RecordDto;
}) {
  const { t } = useTranslation('record');
  if (field.ai === undefined || field.ai.locked) return null;
  const state = aiCellStateOf(record, field.field.id);
  const value = record.fields[field.field.id];
  if (state === undefined && (value === null || value === undefined || value === '')) return null;
  const Icon = state === 'failed' ? CircleAlert : state === 'paused' ? CirclePause : Sparkles;
  return (
    <p
      className={cn(
        'flex items-center gap-1 px-2 pt-0.5 text-label font-normal',
        state === 'failed' ? 'text-danger' : 'text-fg-muted',
      )}
      data-testid="ai-marker"
    >
      <Icon
        aria-hidden="true"
        className={cn('size-3 shrink-0', state === undefined && 'text-accent')}
      />
      {t(state === undefined ? 'ai.generated' : `ai.${state}`)}
    </p>
  );
}
